import{_ as t,o as s,c as l,j as e,a as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/75-恋爱难的时代.md","filePath":"books/xialiu-shehui/75-恋爱难的时代.md","lastUpdated":1794732511000}'),r={name:"books/xialiu-shehui/75-恋爱难的时代.md"};function n(i,a,d,p,_,u){return s(),l("div",null,[...a[0]||(a[0]=[e("h2",{id:"恋爱难的时代",tabindex:"-1"},[o("恋爱难的时代 "),e("a",{class:"header-anchor",href:"#恋爱难的时代","aria-label":'Permalink to "恋爱难的时代"'},"​")],-1),e("p",null,"随着女性中从事综合事务的人数日益增多，使得男性不仅仅同男性竞争，还必须以相同的标准与女性同台竞争，因此很难再像从前那样，男女之间可以产生朴素而单纯的恋情，这也可以认为是造成现今晚婚化、少子化的原因之一。",-1),e("p",null,"如前所述，在女性整体因受到区别对待而“同质化”的时代，男性无疑是得到优厚待遇的，故男性同性之间的关系也比现在更为平等。另一方面，过去男性和女性的关系并不是个人对个人，而是整个群体对整个群体的关系，因而恋爱结婚也就比现在容易得多。",-1),e("p",null,"如果男性和女性不是以群体而是作为个人来面对的话，恋爱必然会变得困难，更何况是寻找配偶这样的终身伴侣，更需要细细地品评和比较对方身上所具备的各种特质，所以相互加深了解的沟通能力也就显得尤为重要。",-1),e("p",null,"就像在落语里出现的场景一样，长辈对某个男子说，你差不多该结婚、该有个家庭了，可你不够沉稳，还是找个可靠一点的女子比较好，所以你就跟这个女孩子交往吧。于是两人没过几天就结婚，开始了夫妇生活。这种情况在现代是不可能出现的。如今的男性和女性已经不是两个各自具有共通性的群体，为了以个人对个人的方式来进行接触，就必须从寻找双方的一致点开始，慢慢地加以沟通。",-1),e("p",null,"这样一来，沟通能力越强的男女，结婚越是容易，越能胜任工作，也越能够享受生活；另一方面，沟通能力越差的男女，就越不容易结婚，越喜欢一个人独处，越没有工作与消费的欲望。也就是说，不管男性还是女性，都会因为沟通能力的不同而被划分为“上流”或“下流”。因此，“上流”男性与“上流”女性、“下流”男性与“下流”女性结合起来才会更加容易。",-1)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
